steps.script:
var t = GameState.state.units["U_TANKBUSTAS_A"]
t["embarked_in"] = "U_TRUKK_A"
for m in t.models:
	m["position"] = null
var tr = GameState.state.units["U_TRUKK_A"]
if not tr.transport_data.has("embarked_units"):
	tr.transport_data["embarked_units"] = []
tr.transport_data.embarked_units.append("U_TANKBUSTAS_A")
return int(tr.transport_data.get("firing_deck", 0))

var w = RulesEngine.get_unit_weapons("U_TRUKK_A", GameState.state)
var fd = ""
for mid in w:
	if RulesEngine.ork11e_is_firing_deck_bearer(mid):
		fd = str(w[mid][0])
var c = tree.root.get_node("Main").shooting_controller
var fc = c._calc_weapon_expected_damage(fd, "U_CUSTODIAN_GUARD_C")
var own = c._calc_weapon_expected_damage("dual_big_shoota_ranged", "U_CUSTODIAN_GUARD_C")
return fd != "" and ("Drive-by Bustin'" in fc.get("active_tags", [])) and not ("Drive-by Bustin'" in own.get("active_tags", []))

var p = PhaseManager.get_current_phase_instance()
for d in p.dice_log:
	if typeof(d) == TYPE_DICTIONARY and (str(d.get("context", "")) == "to_hit" and not ("Drive-by Bustin" in str(d.get("modifier_ledger", [])))):
		return true
return false

var p = PhaseManager.get_current_phase_instance()
for d in p.dice_log:
	if typeof(d) == TYPE_DICTIONARY and (str(d.get("context", "")) == "to_hit" and "Drive-by Bustin" in str(d.get("modifier_ledger", [])) and (int(d.get("modifiers_applied", 0)) & int(RulesEngine.HitModifier.PLUS_ONE)) != 0):
		return true
return false
